import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.DgVVaeR-.js";const s="/Palleria/assets/ranking.Bf6LO1fJ.png",o="/Palleria/assets/illust_page.hJ72Uieh.png",l="/Palleria/assets/novel.GX3rLInO.png",g=JSON.parse('{"title":"作品を見る","description":"","frontmatter":{"title":"作品を見る"},"headers":[],"relativePath":"user/browse.md","filePath":"user/browse.md","lastUpdated":1791090709000}'),n={name:"user/browse.md"};function p(c,a,h,d,f,u){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="作品を見る" tabindex="-1">作品を見る <a class="header-anchor" href="#作品を見る" aria-label="Permalink to &quot;作品を見る&quot;">​</a></h1><h2 id="ホームとランキング" tabindex="-1">ホームとランキング <a class="header-anchor" href="#ホームとランキング" aria-label="Permalink to &quot;ホームとランキング&quot;">​</a></h2><p>ホームでは「フィード」と「フォロー中」を切り替えます。ランキングでは画面上部の項目からデイリー・男女別・週間などの種類を選びます。表示対象は年齢制限・ミュートなどの設定にも従います。</p><figure class="app-screenshot"><p><img src="'+s+'" alt="デイリー・男性・女性・週間の切り替えがあるランキング画面" loading="lazy"></p><figcaption>ランキングの表示例。上部の項目を切り替えて作品を探せます。</figcaption></figure><h2 id="イラスト・マンガ" tabindex="-1">イラスト・マンガ <a class="header-anchor" href="#イラスト・マンガ" aria-label="Permalink to &quot;イラスト・マンガ&quot;">​</a></h2><p>カードをタップすると作品詳細を開きます。詳細には画像、ページ数、タイトル、作者、タグ、説明文などが表示されます。作者を押すとプロフィール、タグを押すとそのタグの検索へ進みます。</p><figure class="app-screenshot"><p><img src="'+o+'" alt="ページ表示、作者、タグ、説明文が並ぶイラスト詳細" loading="lazy"></p><figcaption>作品詳細の例。複数ページ作品ではページ数も表示されます。</figcaption></figure><p>画像ビューアではピンチ・ダブルタップによる拡大縮小、複数ページの移動を利用できます。マンガの読み方や画質は表示設定に従います。カードの長押しはQuickPeek、一覧の2本指ピンチはグリッド列数の変更です。</p><h2 id="うごイラ" tabindex="-1">うごイラ <a class="header-anchor" href="#うごイラ" aria-label="Permalink to &quot;うごイラ&quot;">​</a></h2><p>うごイラ作品はフレーム画像を取得して再生します。保存時にはGIF・MP4への変換処理があります。静止画と異なり、フレーム取得や変換に時間がかかる場合があります。</p><h2 id="小説リーダー" tabindex="-1">小説リーダー <a class="header-anchor" href="#小説リーダー" aria-label="Permalink to &quot;小説リーダー&quot;">​</a></h2><p>小説一覧は小説へのボタンから開きます。ホームの小説ボタンを非表示にしている場合は「もっと見る」に小説の入口が表示されます。</p><p>横書き・縦書き、文字サイズ・行間・背景などを表示設定から調整できます。目次やページ位置の操作で読みたい場所に移動できます。</p><figure class="app-screenshot"><p><img src="'+l+'" alt="セピア背景の縦書き小説と目次・表示設定ボタン" loading="lazy"></p><figcaption>縦書き表示の例。本文下部にはページ位置、目次、表示設定があります。</figcaption></figure><h3 id="読み上げ-tts" tabindex="-1">読み上げ（TTS） <a class="header-anchor" href="#読み上げ-tts" aria-label="Permalink to &quot;読み上げ（TTS）&quot;">​</a></h3><p>小説本文を端末のText-to-Speechエンジンで読み上げます。音声、速度、ピッチを変更でき、再生・一時停止などを操作できます。対応する声や言語は端末のTTSエンジンによって異なります。</p><p>一時停止からの再開では、エンジンが通知した読み上げ範囲の開始位置を保持します。正確な途中再開には範囲通知に対応したエンジンが必要です。バックグラウンド再生は通知とMediaSessionを使用しますが、OSの強制終了後まで再生継続を保証するものではありません。</p><h2 id="キーボード・マウス" tabindex="-1">キーボード・マウス <a class="header-anchor" href="#キーボード・マウス" aria-label="Permalink to &quot;キーボード・マウス&quot;">​</a></h2><p>画像・小説では矢印キーやSpaceでページ移動、Fで全画面切り替え、Ctrl+Wで閉じる操作ができます。画像ビューアではCtrl+Sで表示ページを保存し、小説ではJ / Kで段落移動できます。詳しくは<a href="/Palleria/dev/chromeos">デスクトップ入力</a>を参照してください。</p>',19)])])}const m=e(n,[["render",p]]);export{g as __pageData,m as default};
